import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_softmax_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_softmax_bias_scale_sigmoid_kernel(
    const float* x, const float* bias, float scaling_factor, float* out,
    int N, int C, int H, int W) {

    extern __shared__ float shared[];

    int nhw = blockIdx.x;
    int n = nhw / (H * W);
    int hw = nhw % (H * W);
    int h = hw / W;
    int w = hw % W;

    int c = threadIdx.x;
    if (c >= C) return;

    int idx = n*C*H*W + c*H*W + h*W + w;
    float val = x[idx];

    shared[c] = val;
    __syncthreads();

    for(int s=blockDim.x/2; s>0; s>>=1) {
        if(c < s) shared[c] = fmaxf(shared[c], shared[c+s]);
        __syncthreads();
    }
    float max_val = shared[0];
    __syncthreads();

    shared[c] = expf(val - max_val);
    __syncthreads();

    for(int s=blockDim.x/2; s>0; s>>=1) {
        if(c < s) shared[c] += shared[c+s];
        __syncthreads();
    }
    float sum = shared[0];

    float result = (shared[c]/sum) + bias[c];
    result = 1.0f / (1.0f + expf(-result*scaling_factor));
    out[idx] = result;
}

torch::Tensor fused_softmax_bias_scale_sigmoid_cuda(
    torch::Tensor x, torch::Tensor bias, float scaling_factor) {

    auto out = torch::empty_like(x);
    int C = x.size(1);
    dim3 grid(x.size(0)*x.size(2)*x.size(3));
    dim3 block(C);

    fused_softmax_bias_scale_sigmoid_kernel<<<grid, block, C*sizeof(float)>>>(
        x.data_ptr<float>(), bias.data_ptr<float>(), scaling_factor,
        out.data_ptr<float>(), x.size(0), C, x.size(2), x.size(3));

    return out;
}
"""

fused_softmax = load_inline(
    name='fused_softmax',
    cpp_sources="torch::Tensor fused_softmax_bias_scale_sigmoid_cuda(torch::Tensor x, torch::Tensor bias, float scaling_factor);",
    cuda_sources=fused_softmax_source,
    functions=['fused_softmax_bias_scale_sigmoid_cuda'],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias_shape, scaling_factor):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, 
                                               stride=stride, padding=padding, 
                                               output_padding=output_padding)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.scaling_factor = scaling_factor

    def forward(self, x):
        x = self.conv_transpose(x)
        x = fused_softmax.fused_softmax_bias_scale_sigmoid_cuda(x, self.bias, self.scaling_factor)
        return x
